using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Freyja.WorldBuilder.Editor;
public static class Access023 {
 [Serializable]public class Entry {public string id;public Vector3 door;public Vector3 road;public Vector3[] points;}
 public static object Main(){var root=GameObject.Find("Island023");var terrain=root.GetComponentInChildren<Terrain>();var td=terrain.terrainData;var routes=Island023.Routes();var buildings=root.transform.Find("Construções — 12 casas e 5 serviços");var entries=new List<Entry>();var all=routes.SelectMany(r=>r.points).ToArray();
 foreach(Transform b in buildings){var door=b.GetComponentsInChildren<Renderer>().First(r=>r.name.StartsWith("Porta"));var front=b.rotation*Vector3.back;var target=door.bounds.center+front*.72f;target.y=b.position.y;var candidates=all.Where(p=>Vector3.Dot(Vector3.ProjectOnPlane(p-target,Vector3.up),front)>-.5f).OrderBy(p=>(new Vector2(p.x-target.x,p.z-target.z)).sqrMagnitude);var nearest=all.OrderBy(p=>new Vector2(p.x-target.x,p.z-target.z).sqrMagnitude).First();var start=candidates.FirstOrDefault();bool around=!candidates.Any()||Vector3.Distance(start,target)>Vector3.Distance(nearest,target)+5;var anchors=new List<Vector3>();if(around){start=nearest;anchors.Add(start);var right=b.rotation*Vector3.right;float side=Mathf.Sign(Vector3.Dot(start-b.position,right));var col=b.GetComponent<BoxCollider>();var corner=b.position+right*side*(col.size.x/2+1.8f)+front*(col.size.z/2+1.5f);corner.y=b.position.y;var sideStart=b.position+right*side*(col.size.x/2+1.8f)+front*Vector3.Dot(start-b.position,front);sideStart.y=start.y;anchors.Add(sideStart);anchors.Add(corner);}else anchors.Add(start);anchors.Add(target);var points=new List<Vector3>();for(int k=1;k<anchors.Count;k++){var from=anchors[k-1];var to=anchors[k];int count=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(from,to)));for(int i=0;i<=count;i++){float f=i/(float)count;var p=Vector3.Lerp(from,to,f);p.y=Mathf.Lerp(from.y,to.y,Mathf.SmoothStep(0,1,f));points.Add(p);}}entries.Add(new Entry{id=b.name,door=target,road=start,points=points.ToArray()});}
 int n=td.heightmapResolution;var h=td.GetHeights(0,0,n,n);foreach(var e in entries){foreach(var p in e.points){int cx=Mathf.RoundToInt((p.x+80)/160*(n-1)),cz=Mathf.RoundToInt((p.z+80)/160*(n-1));int radius=13;for(int z=Mathf.Max(0,cz-radius);z<=Mathf.Min(n-1,cz+radius);z++)for(int x=Mathf.Max(0,cx-radius);x<=Mathf.Min(n-1,cx+radius);x++){float wx=x/(float)(n-1)*160-80,wz=z/(float)(n-1)*160-80;float d=Vector2.Distance(new Vector2(wx,wz),new Vector2(p.x,p.z));float f=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.05f,3.8f,d));h[z,x]=Mathf.Lerp(h[z,x],(p.y+5)/40,f);}}}td.SetHeights(0,0,h);EditorUtility.SetDirty(td);
 var old=root.transform.Find("Acessos às 17 portas");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var parent=new GameObject("Acessos às 17 portas");parent.transform.SetParent(root.transform);foreach(var e in entries){var route=new Island023.Route("Acesso "+e.id,1.8f,e.points);typeof(Island023).GetMethod("PathMesh",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{route,parent.transform,terrain});}
 foreach(Transform g in root.transform.Find("Pedras e árvores editáveis")){if(entries.Any(e=>e.points.Any(p=>Vector2.Distance(new Vector2(p.x,p.z),new Vector2(g.position.x,g.position.z))<2.8f)))g.gameObject.SetActive(false);}
 // Reacomodar vias existentes depois da conformação dos acessos.
 foreach(Transform g in root.transform.Find("Ruas e caminhos")){if(g.name=="Praça central")continue;var mesh=g.GetComponent<MeshFilter>().sharedMesh;var v=mesh.vertices;for(int i=0;i<v.Length;i++)v[i].y=terrain.SampleHeight(v[i])-5+.055f;mesh.vertices=v;mesh.RecalculateNormals();EditorUtility.SetDirty(mesh);}
 File.WriteAllText("/Users/bruno.duartec/Documents/Projects/Freyja/Artifacts/Island023/access-layout.json",Newtonsoft.Json.JsonConvert.SerializeObject(entries,Newtonsoft.Json.Formatting.Indented,new Newtonsoft.Json.JsonSerializerSettings{ReferenceLoopHandling=Newtonsoft.Json.ReferenceLoopHandling.Ignore}));AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.scene);return entries.Select(e=>new{id=e.id,length=Vector3.Distance(e.road,e.door)}).ToArray();}
}
